/*!
 * Minimal local shim for htmx-style attributes used in this project.
 * Replace with official htmx distribution for full feature support.
 */
(function () {
  if (window.htmx) return;
  window.htmx = { version: "local-shim-0.1.0" };

  function closestWithAttr(el, attr) {
    while (el && el !== document.body) {
      if (el.hasAttribute && el.hasAttribute(attr)) return el;
      el = el.parentElement;
    }
    return null;
  }

  document.addEventListener("submit", async function (event) {
    const form = closestWithAttr(event.target, "hx-post");
    if (!form) return;
    event.preventDefault();

    const endpoint = form.getAttribute("hx-post");
    const targetSelector = form.getAttribute("hx-target");
    const target = targetSelector ? document.querySelector(targetSelector) : null;
    const swap = form.getAttribute("hx-swap") || "innerHTML";

    const payload = Object.fromEntries(new FormData(form).entries());
    const response = await fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    const text = await response.text();
    if (target) {
      if (swap === "outerHTML") target.outerHTML = text;
      else target.innerHTML = text;
    }
  });
})();
